<?php
declare(strict_types=1);
function stage58Document(string $lang,array $texts,array $refs):array {return $lang==='pt'?referenceDocument($texts,$refs):stage57Document($lang,$texts,$refs);}
function stage58Results(string $lang,array $texts,array $refs):array {return apaResults(stage58Document($lang,$texts,$refs),$lang);}
function stage58Ref(string $date='2020, May 2',string $author='Silva, A.',string $tail=''):string {return $author.' ('.$date.'). Synthetic work. Example Publisher.'.$tail;}
foreach(['pt','en','es']as$lang){
 foreach(['2020, May 2','2020, 2 de maio','2020, February 29','2020, 29 de fevereiro']as$date){
  foreach(['(Silva, 2020).','Silva (2020).']as$text){test('data completa única liga chave sem certificar fonte '.$lang.md5($date.$text),function()use($lang,$date,$text){$refs=[stage58Ref($date)];$d=stage58Document($lang,[$text],$refs);$before=$d;$r=apaResults($d,$lang);$a=$r['references.apa7']['evidence']['analysis'];same('conforme',$r['references.citation_matching']['status']);same(1,$a['full_date_references']);same(1,$a['matched_citations']);same(0,$a['unresolved_citations']);same('indeterminado',$r['references.apa7.citation_format']['status']);same('manual_review_required',$r['references.apa7']['evidence']['admission_policy']['decision']);same(false,$a['et_al_context_complete']);same($before,$d);same(null,\Estrabao\Document\ReferenceAnalysis::parseEntry($refs[0]));});}
 }
 foreach(['2020, May','2020, Foo 2','2020, May 32','2019, February 29','2020a, May 2','2020-05-02','2020, 2 de mayo']as$date){test('data fora do subconjunto não produz falsa ausência '.$lang.$date,function()use($lang,$date){$r=stage58Results($lang,['(Silva, 2020).'],[stage58Ref($date)]);same('indeterminado',$r['references.citation_matching']['status']);same(0,$r['references.apa7']['evidence']['analysis']['full_date_references']);same(1,$r['references.apa7']['evidence']['analysis']['unparsed_references']);});}
 foreach(['two_dates','duplicate','year_only','mixed_suffix','suffix','initials','unparsed','original','unknown_original','different_author_count']as$case){test('obra ou edição ambígua permanece humana '.$lang.$case,function()use($lang,$case){$refs=[stage58Ref()];$text='(Silva, 2020).';if($case==='two_dates'){$refs[]=stage58Ref('2020, May 10');}elseif($case==='duplicate'){$refs[]=$refs[0];}elseif($case==='year_only'){$refs[]=stage58Ref('2020');}elseif($case==='mixed_suffix'){$refs[]=stage58Ref('2020a');$text='(Silva, 2020a).';}elseif($case==='suffix'){$text='(Silva, 2020a).';}elseif($case==='initials'){$refs[]=stage58Ref('2020, May 10','Silva, B.');}elseif($case==='unparsed'){$refs[]='Unrecognized source data';}elseif($case==='original'){$refs=[stage58Ref('2020, May 2','Silva, A.',' (Original work published 1900)')];}elseif($case==='unknown_original'){$refs=[stage58Ref('2020, May 2','Silva, A.',' (Original work published unknown)')];}else{$refs=[stage58Ref('2020, May 2','Silva, A., & Costa, B.')];}
 $r=stage58Results($lang,[$text],$refs);$a=$r['references.apa7']['evidence']['analysis'];same('indeterminado',$r['references.citation_matching']['status']);same(1,$a['ambiguous_matches']);same(0,$a['matched_citations']);same('manual_review_required',$r['references.apa7']['evidence']['admission_policy']['decision']);same(true,in_array('full_date_source_review',$a['citation_style_samples'][0]['issues'],true));
 });}
 foreach(['normal_first','full_first','full_then_unknown','normal_then_unknown']as$case){test('duas referências coladas não fecham o contexto '.$lang.$case,function()use($lang,$case){$a=stage58Ref();$b=stage58Ref('2019','Costa, B.');$refs=[$case==='normal_first'?$b.' '.$a:($case==='full_first'?$a.' '.$b:($case==='full_then_unknown'?$a.' '.stage58Ref('2020,05/02','Costa, B.'):$b.' '.stage58Ref('2020,05/02','Silva, A.')))];$r=stage58Results($lang,['(Absent, 2018).'],$refs);same('indeterminado',$r['references.citation_matching']['status']);same(1,$r['references.apa7']['evidence']['analysis']['unparsed_references']);});}
 test('ausência de chave só é provada em contexto fechado '.$lang,function()use($lang){$r=stage58Results($lang,['(Absent, 2018).'],[stage58Ref()]);same('não conforme',$r['references.citation_matching']['status']);same('not_accepted',$r['references.apa7']['evidence']['admission_policy']['decision']);});
 test('erro local comprovado ainda bloqueia citação com data completa '.$lang,function()use($lang){$r=stage58Results($lang,['Silva & Costa (2020).'],[stage58Ref('2020, May 2','Silva, A., & Costa, B.')]);same('conforme',$r['references.citation_matching']['status']);same('não conforme',$r['references.apa7.citation_format']['status']);same('not_accepted',$r['references.apa7']['evidence']['admission_policy']['decision']);});
 test('nova data reconhecida não fortalece prova de sufixos ou et al '.$lang,function()use($lang){$r=stage58Results($lang,['(Silva, 2020b).','(Costa et al., 2021).'],['Costa, A., Alves, B., & Lima, C. (2021). Other work. Publisher.','Costa, A., Brito, B., & Reis, C. (2021). Another work. Publisher.',stage58Ref()]);same('manual_review_required',$r['references.apa7']['evidence']['admission_policy']['decision']);same(false,$r['references.apa7']['evidence']['analysis']['et_al_context_complete']);});
 test('secundária de data completa liga somente fonte consultada '.$lang,function()use($lang){$marker=['pt'=>'como citado em','en'=>'as cited in','es'=>'como se citó en'][$lang];$r=stage58Results($lang,['(Original, 1900, '.$marker.' Silva, 2020).'],[stage58Ref()]);$a=$r['references.apa7']['evidence']['analysis'];same(1,$a['matched_citations']);same(0,$a['unresolved_citations']);same(true,$a['citation_samples'][0]['secondary']);same('manual_review_required',$r['references.apa7']['evidence']['admission_policy']['decision']);});
 test('apud com data completa não é liberado '.$lang,function()use($lang){$r=stage58Results($lang,['(Original, 1900, apud Silva, 2020).'],[stage58Ref()]);same('not_accepted',$r['references.apa7']['evidence']['admission_policy']['decision']);});
 test('instituição com data completa continua fora da projeção pessoal '.$lang,function()use($lang){$r=stage58Results($lang,['(WHO, 2020).'],['World Health Organization. (2020, May 2). Synthetic report. Publisher.']);same('indeterminado',$r['references.citation_matching']['status']);same(0,$r['references.apa7']['evidence']['analysis']['full_date_references']);});
 test('data completa não determina identidade com ano original '.$lang,function()use($lang){$r=stage58Results($lang,['(Silva, 1900).'],[stage58Ref('2020, May 2','Silva, A.',' (Original work published 1900)')]);same('indeterminado',$r['references.citation_matching']['status']);same('manual_review_required',$r['references.apa7']['evidence']['admission_policy']['decision']);});
}
